<template>
  <dialog ref="surface" class="creator-panel" :aria-modal="narrow ? 'true' : 'false'" aria-labelledby="creator-panel-title" @cancel.prevent="emit('close')" @click.capture="routeInternalLink">
    <header class="panel-heading">
      <div><p class="eyebrow">博主资料</p><h2 id="creator-panel-title">{{ creatorId === null ? '新增博主' : detail?.name ?? '正在读取…' }}</h2>
        <div v-if="detail" class="identity-tags"><span>{{ detail.rating ?? '待分类' }}</span><span>{{ preferenceLabel(detail.preference) }}</span><span>{{ detail.isActive ? '启用' : '已停用' }}</span></div>
      </div>
      <button type="button" aria-label="关闭管理面板" :disabled="busy" @click="emit('close')">关闭</button>
    </header>
    <p v-if="error" role="alert" class="error">{{ error }} <button v-if="conflicted" type="button" :disabled="busy" @click="reloadEditing">放弃当前标签改动并重新读取</button></p>
    <p v-if="notice" role="status" class="notice">{{ notice }}</p>
    <p v-if="loading" role="status">正在读取博主资料…</p>
    <template v-if="detail">
      <dl class="panel-metrics"><div v-for="metric in metrics" :key="metric.label"><dt>{{ metric.label }}</dt><dd>{{ metric.value }}</dd></div></dl>
      <nav class="panel-tabs" role="tablist" aria-label="管理资料标签">
        <button v-for="item in tabs" :id="`creator-tab-${item.id}`" :key="item.id" type="button" role="tab" :aria-selected="tab === item.id" :aria-controls="`creator-content-${item.id}`" :tabindex="tab === item.id ? 0 : -1" @click="chooseTab(item.id)" @keydown="tabKey($event,item.id)">{{ item.label }}<span v-if="dirtyTabs.includes(item.id)" aria-label="未保存"> ·</span></button>
      </nav>
    </template>
    <div v-if="detail && tab === 'overview'" id="creator-content-overview" role="tabpanel" aria-labelledby="creator-tab-overview" class="tab-body">
      <div class="quick-links"><a :href="`/library/${detail.id}`">查看图库</a><button type="button" @click="emit('catalog',detail.id)">资源目录</button></div>
      <section><h3>来源合集</h3><p v-if="!detail.collections.length" class="hint">尚无来源记录，不能据此判断已全部收齐。</p>
        <ul class="records"><li v-for="collection in detail.collections" :key="collection.id"><strong>{{ collection.title }}</strong><p class="hint">{{ sourceLabel(collection.source) }} · 来源声明 {{ collection.declaredWorkCount ?? '未知' }} 套 · {{ formatTime(collection.observedAt) }}</p><a v-if="safeUrl(collection.url)" :href="collection.url!" target="_blank" rel="noopener noreferrer">查看来源合集</a></li></ul>
      </section>
      <section><h3>已知待收录 · {{ detail.missingWorks }}</h3><p v-if="!detail.missing.length" class="hint">{{ detail.remoteWorks ? '当前账本没有已知缺失作品。' : '尚无来源作品可供比较。' }}</p><ul class="records"><li v-for="work in detail.missing" :key="work.workId">{{ work.sourceOrderLabel ?? (work.sourceOrder === null ? '未编号' : `NO.${work.sourceOrder}`) }} · {{ work.title }}<small>{{ sourceLabel(work.source) }}</small></li></ul></section>
      <section><h3>待核查 · {{ detail.unresolvedLocalWorks }}</h3><p v-if="!detail.unresolved.length" class="hint">当前没有待核查本地作品。</p><ul class="records"><li v-for="(folder,index) in detail.unresolved" :key="`${folder.relativePath}:${index}`"><strong>{{ folder.folderName }}</strong><small>{{ folder.relativePath }} · {{ folder.status === 'ambiguous' ? '对应存在歧义' : '尚未确认对应' }}</small></li></ul></section>
      <section><h3>本地入库记录</h3><p v-if="historyError" class="error">{{ historyError }}</p><p v-else-if="historyLoading" class="hint">正在读取…</p><p v-else-if="!history.length" class="hint">暂无网页本地接纳记录；此处不是跨来源统一执行历史。</p><ul class="records"><li v-for="batch in history" :key="batch.id"><a :href="batch.collectionId ? `/creator-admission/local?collection=${encodeURIComponent(batch.collectionId)}` : `/creator-admission/local/${detail.id}?batch=${encodeURIComponent(batch.id)}`">{{ formatTime(batch.createdAt) }} · {{ batchLabel(batch.state) }}</a><small>{{ batch.totals.completed }} 已完成 / {{ batch.totals.total }} 个目录</small></li></ul><p v-if="historyTotal > history.length" class="hint">展示最近 {{ history.length }} 项，共 {{ historyTotal }} 项；进入入库记录可继续查看。</p></section>
    </div>
    <form v-if="creatorId === null || (detail && tab === 'profile')" id="creator-content-profile" role="tabpanel" aria-labelledby="creator-tab-profile" class="tab-body profile-form" @submit.prevent="saveProfile">
      <p v-if="editingLoading" role="status">正在读取可编辑资料…</p>
      <fieldset :disabled="busy || !canEdit || (creatorId !== null && !editing)">
        <label>名称<input v-model="draft.name" required maxlength="255" /></label>
        <div class="field-pair"><label>偏好<select v-model="draft.preference"><option :value="null">未设置</option><option value="liked">喜欢</option><option value="kept">保留</option></select></label><label>分级<select v-model="draft.rating"><option :value="null">待分类</option><option>R15</option><option>R18</option></select></label></div>
        <template v-if="detail"><h3>手工别名</h3><ul class="editable-list"><li v-for="(alias,index) in manualAliases" :key="index"><span>{{ alias }}</span><button type="button" @click="manualAliases.splice(index,1)">移除</button></li></ul><div class="inline-input"><label>添加手工别名<input v-model="aliasInput" maxlength="255" @keydown.enter.prevent="stageAlias" /></label><button type="button" :disabled="!aliasInput.trim()" @click="stageAlias">添加</button></div><p class="hint">别名增删与名称、偏好、分级一并保存。</p><h3>来源 / 历史别名</h3><ul class="records"><li v-for="alias in readonlyAliases" :key="alias.id">{{ alias.alias }} <small>{{ sourceLabel(alias.source) }} · 只读</small></li></ul><p v-if="!readonlyAliases.length" class="hint">暂无只读别名。</p></template>
        <aside v-if="collisions.length" class="warning"><p>可能为已有身份，请核对后再保存：</p><ul><li v-for="item in collisions" :key="item.id">#{{ item.id }} {{ item.name }}</li></ul><label class="check"><input v-model="draft.confirmDistinct" type="checkbox" />我已核对，这是不同的人，允许同名</label></aside>
      </fieldset>
      <footer class="save-bar"><span>{{ canEdit ? '只保存此标签中的资料' : '当前无编辑权限' }}</span><button class="primary" :disabled="busy || !canEdit || (creatorId !== null && (!editing || !profileDirty))">{{ busy ? '正在保存…' : creatorId === null ? '创建博主' : '保存资料' }}</button></footer>
      <section v-if="detail" class="danger-zone"><h3>身份状态</h3><p class="hint">停用保留既有作品、来源及任务，只影响未来规划与默认展示。恢复不自动生成任务。</p><p class="hint">来源 {{ detail.impact.sources }} · 合集 {{ detail.impact.collections }} · 本地作品 {{ detail.impact.localWorks }} · 未完成下载 {{ detail.impact.unfinishedDownloadTasks }}</p><button type="button" :disabled="busy || !canEdit || profileDirty || directoriesDirty" @click="stateConfirm=true">{{ detail.isActive ? '停用博主' : '恢复博主' }}</button>
        <p v-if="profileDirty || directoriesDirty" class="hint">先保存或放弃资料 / 目录草稿，再变更身份状态。</p><aside v-if="stateConfirm" class="warning"><p>确认{{ detail.isActive ? '停用' : '恢复' }} {{ detail.name }}？未保存的资料不会随此动作提交。</p><button type="button" :disabled="busy" @click="changeActive">确认变更</button><button type="button" :disabled="busy" @click="stateConfirm=false">取消</button></aside>
<div v-if="detail.seedSource === 'manual' && !detail.isActive" aria-label="删除未使用博主" data-test="unused-creator-deletion"><h3>删除未使用博主</h3><p class="hint">只适用于手工创建、已停用且没有业务引用的身份。删除无法通过恢复找回，不删除媒体、作品或任务。</p><button type="button" :disabled="busy || !canEdit || dirtyTabs.length > 0" data-test="preview-creator-deletion" @click="previewDeletion">检查是否可删除</button><p v-if="dirtyTabs.length" class="hint">先保存或放弃资料、目录或来源草稿，再检查删除条件。</p><aside v-if="deletion" class="warning" data-test="creator-deletion-preview"><strong>#{{ deletion.creatorId }} {{ deletion.name }}</strong><ul v-if="deletion.blockers.length"><li v-for="blocker in deletion.blockers" :key="blocker.code">{{ blocker.label }} · {{ blocker.count }}</li></ul><template v-else-if="deletion.eligible"><p>将删除此身份及 {{ deletion.removableAliases }} 条手工别名。提交时再次核对引用。</p><button type="button" class="danger" :disabled="busy || !deletion.confirmationToken" data-test="confirm-creator-deletion" @click="deleteCreator">确认删除博主</button></template><p v-else>当前不符合删除条件。</p><button type="button" :disabled="busy" @click="deletion=null">取消删除</button></aside></div>
      </section>
    </form>
    <form v-if="detail && tab === 'directories'" id="creator-content-directories" role="tabpanel" aria-labelledby="creator-tab-directories" class="tab-body" @submit.prevent="saveDirectories">
      <div class="quick-links"><a :href="`/creator-admission/local/${detail.id}`">为该博主入库</a></div><p class="hint">仅进入既有入库页面，并带入该博主身份。</p><p v-if="editingLoading" role="status">正在读取目录设置…</p>
      <fieldset :disabled="busy || !canEdit || !editing"><h3>已关联目录</h3><p v-if="!selectedFolders.length" class="hint">尚未选择本地目录。</p><ul class="editable-list"><li v-for="folder in selectedFolders" :key="folder.id"><span>{{ folder.folderPath }}<small>{{ folder.workCount }} 套 · {{ linkedLabel(folder.matchStatus) }}</small></span><button type="button" @click="linkedFolderIds=linkedFolderIds.filter(id=>id!==folder.id)">拟解除</button></li></ul><div class="inline-input"><label>可关联目录<select v-model="folderInput"><option :value="null">选择未关联目录</option><option v-for="folder in availableFolders" :key="folder.id" :value="folder.id">{{ folder.folderPath }} · {{ folder.workCount }} 套</option></select></label><button type="button" :disabled="folderInput===null" @click="stageFolder">拟关联</button></div>
        <h3>首选入库目录</h3><p v-if="editing?.destination" :class="['hint',{'error': destinationUnavailable}]">{{ editing.destination.message }}<template v-if="editing.destination.resolvedCreatorDirectory">：{{ editing.destination.resolvedCreatorDirectory }}</template></p><label>首选目录<select v-model="preferredFolderId"><option :value="null">不显式选择（沿用有效回退规则）</option><option v-for="folder in destinationOptions" :key="folder.id" :value="folder.id" :disabled="!folder.valid">{{ folder.path }}{{ folder.valid ? '' : ` · ${folder.reason}` }}</option></select></label><p v-if="invalidPreferred" class="error">首选目录不在保存后的有效关联范围内，请重新选择或取消首选。</p>
        <aside v-if="directoriesDirty" class="warning"><h3>本次目录变化</h3><p v-for="folder in removedFolders" :key="`remove-${folder.id}`">解除关联：{{ folder.folderPath }}</p><p v-for="folder in addedFolders" :key="`add-${folder.id}`">新增关联：{{ folder.folderPath }}</p><p v-if="preferredFolderId !== savedPreferredGalleryId">首选目录将变更为：{{ destinationOptions.find(item=>item.id===preferredFolderId)?.path ?? '不显式选择' }}</p></aside>
      </fieldset><footer class="save-bar"><span>只保存目录关系与首选设置；不移动、扫描或生成任务。</span><button class="primary" :disabled="busy || !canEdit || !editing || !directoriesDirty || invalidPreferred">{{ busy ? '正在保存…' : '保存目录设置' }}</button></footer>
    </form>
    <div v-if="detail && sourcesVisited" v-show="tab === 'sources'" id="creator-content-sources" role="tabpanel" aria-labelledby="creator-tab-sources" class="tab-body">
      <section><h3>检查来源</h3><FirstCollectionSelector :creator="detail" :active="tab === 'sources'" :disabled="busy || !canEdit || !detail.isActive" @planned="sourcePlanned" /></section><section><h3>准备缺失获取任务</h3><p class="hint">依据明确来源对应规划当前博主的已知缺失，不执行网盘转存或本地入库。</p><button type="button" :disabled="busy || !canEdit || !detail.isActive || !detail.missing.length" @click="emit('plan-downloads',detail.id)">生成此博主的缺失获取任务</button></section>
      <SourceEvidencePanel ref="sourcePanel" :creator="detail" />
      <section><h3>作品来源</h3><p v-if="!visibleSources.length" class="hint">暂无当前来源。</p><ul class="records"><li v-for="source in visibleSources" :key="`${source.source}:${source.sourceCreatorId}`"><strong>{{ sourceLabel(source.source) }} · {{ source.displayName }}</strong><a v-if="safeUrl(source.url)" :href="source.url!" target="_blank" rel="noopener noreferrer">查看来源</a></li></ul></section>
    </div>
    <details v-if="detail" class="technical"><summary>技术信息</summary><p>稳定 ID #{{ detail.id }} · {{ detail.seedSource }} / {{ detail.seedSourceCreatorId }}</p><ul><li v-for="folder in detail.localFolders" :key="folder.id">目录 #{{ folder.id }} · 桥接 #{{ folder.catalogFolderId ?? '无' }} · {{ folder.matchStatus }} / {{ folder.matchMethod ?? '无' }}</li><li v-for="source in detail.sources" :key="`${source.source}:${source.sourceCreatorId}`">{{ source.source }} / {{ source.sourceCreatorId }}</li><li v-for="collection in detail.collections" :key="collection.id">合集 #{{ collection.id }} / {{ collection.sourceCollectionId }}</li></ul></details>
    <dialog ref="leaveDialog" class="leave-dialog" aria-labelledby="leave-title" @cancel.prevent="resolveLeave(false)"><h3 id="leave-title">尚有未保存改动</h3><p>{{ dirtyLabels.join('、') }}尚未保存。各标签需要分别保存，不会自动一起提交。</p><div class="leave-actions"><button type="button" @click="returnToSave">返回保存</button><button type="button" @click="resolveLeave(true)">放弃更改并继续</button><button type="button" @click="resolveLeave(false)">取消跳转</button></div></dialog>
  </dialog>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { fetchArchiveCatalogCreator } from '../api/gallery';
import { fetchAdmissionBatches } from '../api/local-admission';
import * as api from '../api/managed-creators';
import { RequestError } from '../api/http';
import { useAuthStore } from '../stores/auth';
import { useCreatorReadingStore } from '../stores/creator-reading';
import { pinia } from '../stores/pinia';
import type { ArchiveCatalogCreatorDetail, ManagedLocalFolder } from '../types/api';
import type { AdmissionBatch } from '../types/local-admission';
import FirstCollectionSelector from './FirstCollectionSelector.vue';
import SourceEvidencePanel from './SourceEvidencePanel.vue';

export type CreatorPanelTab = 'overview'|'profile'|'directories'|'sources';
const props=withDefaults(defineProps<{creatorId:number|null;tab:CreatorPanelTab;layoutReady?:boolean}>(),{layoutReady:true});
const emit=defineEmits<{close:[];tab:[value:CreatorPanelTab];changed:[];created:[id:number];deleted:[];catalog:[id:number];'plan-downloads':[id:number];'source-planned':[ids:number[]]}>();
const tabs=[{id:'overview',label:'概览'},{id:'profile',label:'资料'},{id:'directories',label:'本地目录'},{id:'sources',label:'来源与补齐'}] as const;
const auth=useAuthStore(pinia), reading=useCreatorReadingStore(pinia), router=useRouter();
const canEdit=computed(()=>auth.capabilities.canManageLibrary);
const surface=ref<HTMLDialogElement|null>(null), leaveDialog=ref<HTMLDialogElement|null>(null), sourcePanel=ref<InstanceType<typeof SourceEvidencePanel>|null>(null);
const narrow=ref(false), detail=ref<ArchiveCatalogCreatorDetail|null>(null), editing=ref<api.ManagedCreatorEditingState|null>(null);
const loading=ref(false), editingLoading=ref(false), busy=ref(false), error=ref(''), notice=ref(''), conflicted=ref(false), sourcesVisited=ref(false);
const draft=reactive<api.ManagedCreatorInput>({name:'',preference:null,rating:null,confirmDistinct:false});
const manualAliases=ref<string[]>([]), aliasInput=ref(''), folderInput=ref<number|null>(null), linkedFolderIds=ref<number[]>([]), preferredFolderId=ref<number|null>(null);
const profileBaseline=ref(''), directoryBaseline=ref(''), profileReady=ref(false), directoriesReady=ref(false);
const profileRevision=ref(''), directoriesRevision=ref('');
const collisions=ref<Array<{id:number;name:string}>>([]), stateConfirm=ref(false), deletion=ref<api.ManagedCreatorDeletionPreview|null>(null);
const history=ref<AdmissionBatch[]>([]), historyTotal=ref(0), historyLoading=ref(false), historyError=ref('');
let generation=0, disposed=false, editingPromise:Promise<void>|null=null, media:MediaQueryList|null=null, leaveResolve:((value:boolean)=>void)|null=null;
const profileValue=()=>JSON.stringify({name:draft.name,preference:draft.preference,rating:draft.rating,manualAliases:[...manualAliases.value].sort()});
const directoryValue=()=>JSON.stringify({linkedFolderIds:[...linkedFolderIds.value].sort((a,b)=>a-b),preferredLocalCreatorFolderId:preferredFolderId.value});
const profileDirty=computed(()=>profileReady.value && (profileValue()!==profileBaseline.value || !!aliasInput.value.trim()));
const directoriesDirty=computed(()=>directoriesReady.value && directoryValue()!==directoryBaseline.value);
const dirtyTabs=computed<CreatorPanelTab[]>(()=>[...(profileDirty.value?['profile' as const]:[]),...(directoriesDirty.value?['directories' as const]:[]),...(sourcePanel.value?.hasUnsavedChanges?['sources' as const]:[])]);
const dirtyLabels=computed(()=>dirtyTabs.value.map(id=>tabs.find(tab=>tab.id===id)!.label));
const readonlyAliases=computed(()=>detail.value?.aliases.filter(alias=>!alias.editable)??[]);
const visibleSources=computed(()=>detail.value?.sources.filter(source=>!['hentaiclub','manual-history'].includes(source.source))??[]);
const folderUniverse=computed(()=>{const result=new Map<number,ManagedLocalFolder>();for(const folder of [...(editing.value?.creator.localFolders??[]),...(editing.value?.creator.unlinkedLocalFolders??[])])result.set(folder.id,folder);return [...result.values()];});
const selectedFolders=computed(()=>folderUniverse.value.filter(folder=>linkedFolderIds.value.includes(folder.id)));
const availableFolders=computed(()=>folderUniverse.value.filter(folder=>!linkedFolderIds.value.includes(folder.id)));
const addedFolders=computed(()=>selectedFolders.value.filter(folder=>!editing.value?.linkedFolderIds.includes(folder.id)));
const removedFolders=computed(()=>editing.value?.creator.localFolders.filter(folder=>!linkedFolderIds.value.includes(folder.id))??[]);
const destinationOptions=computed(()=>selectedFolders.value.map(folder=>{const known=editing.value?.destination.candidates.find(item=>item.localCreatorFolderId===folder.catalogFolderId);return{id:folder.id,path:known?.absolutePath??folder.folderPath,valid:known?.valid??true,reason:known?.unavailableReason??null};}));
const invalidPreferred=computed(()=>preferredFolderId.value!==null&&!destinationOptions.value.some(folder=>folder.id===preferredFolderId.value&&folder.valid));
const preferredGallery=(value:api.ManagedCreatorSavedState)=>value.preferredLocalCreatorFolderId===null?null:value.creator.localFolders.find(folder=>folder.catalogFolderId===value.preferredLocalCreatorFolderId)?.id??-value.preferredLocalCreatorFolderId;
const savedPreferredGalleryId=computed(()=>editing.value?preferredGallery(editing.value):null);
const destinationUnavailable=computed(()=>['selection-required','preferred-unavailable','linked-folders-unavailable'].includes(editing.value?.destination.mode??''));
const metrics=computed(()=>detail.value?[{label:'来源已记录',value:detail.value.remoteWorks},{label:'本地作品',value:detail.value.localWorks},{label:'已确认对应',value:detail.value.matchedWorks},{label:'已知待收录',value:detail.value.missingWorks},{label:'待核查',value:detail.value.unresolvedLocalWorks}]:[]);
const preferenceLabel=(value:string|null)=>value==='liked'?'喜欢':value==='kept'?'保留':'未设置';
const sourceLabel=(value:string)=>({costuan:'Costuan',manual:'手工',hentaiclub:'历史名称','manual-history':'历史名称'}[value]??value);
const linkedLabel=(value:string)=>value==='matched'?'已确认关联':value==='ambiguous'?'对应存在歧义':'拟关联';
const safeUrl=(value:string|null)=>!!value&&/^https?:\/\//iu.test(value);
const formatTime=(value:string)=>Number.isNaN(Date.parse(value))?value:new Date(value).toLocaleString('zh-CN',{hour12:false});
const batchLabel=(value:string)=>({draft:'预览草稿',queued:'等待执行',running:'处理中',completed:'已完成',needs_review:'待核查',interrupted:'已中断',failed:'失败'}[value]??value);
function showError(reason:unknown){error.value=reason instanceof Error?reason.message:'操作失败';const payload=reason instanceof RequestError?reason.payload as {candidates?:Array<{id:number;name:string}>;code?:string}|undefined:undefined;collisions.value=payload?.candidates??[];conflicted.value=payload?.code==='CREATOR_EDIT_CONFLICT';}
function initializeProfile(value:api.ManagedCreatorSavedState){Object.assign(draft,{name:value.creator.name,preference:value.creator.preference,rating:value.creator.rating,confirmDistinct:false});manualAliases.value=value.creator.aliases.filter(alias=>alias.editable).map(alias=>alias.alias);aliasInput.value='';profileRevision.value=value.profileRevision;profileBaseline.value=profileValue();profileReady.value=true;}
function initializeDirectories(value:api.ManagedCreatorSavedState){linkedFolderIds.value=[...value.linkedFolderIds];preferredFolderId.value=preferredGallery(value);folderInput.value=null;directoriesRevision.value=value.directoriesRevision;directoryBaseline.value=directoryValue();directoriesReady.value=true;}
async function ensureEditing(){if(props.creatorId===null||editing.value||editingPromise)return editingPromise;const id=props.creatorId,turn=generation;editingLoading.value=true;editingPromise=(async()=>{try{const value=await api.fetchManagedCreatorEditingState(id);if(disposed||turn!==generation)return;if(value.creator.id!==id)throw Error('资料身份不一致，请重新读取。');editing.value=value;detail.value=value.creator;initializeProfile(value);initializeDirectories(value);}catch(reason){if(turn===generation)showError(reason);}finally{if(turn===generation){editingLoading.value=false;editingPromise=null;}}})();return editingPromise;}
async function loadHistory(id:number,turn:number){historyLoading.value=true;try{const value=await fetchAdmissionBatches(id);if(disposed||turn!==generation)return;history.value=value.items;historyTotal.value=value.total;}catch(reason){if(turn===generation)historyError.value=reason instanceof Error?reason.message:'入库记录读取失败';}finally{if(turn===generation)historyLoading.value=false;}}
async function loadIdentity(){const turn=++generation;detail.value=null;editing.value=null;editingPromise=null;error.value='';notice.value='';collisions.value=[];stateConfirm.value=false;deletion.value=null;conflicted.value=false;profileReady.value=false;directoriesReady.value=false;sourcesVisited.value=false;history.value=[];historyTotal.value=0;historyError.value='';busy.value=false;editingLoading.value=false;historyLoading.value=false;aliasInput.value='';Object.assign(draft,{name:'',preference:null,rating:null,confirmDistinct:false});manualAliases.value=[];profileBaseline.value=profileValue();if(props.creatorId===null){profileReady.value=true;loading.value=false;return;}const id=props.creatorId;loading.value=true;try{const value=await fetchArchiveCatalogCreator(id);if(disposed||turn!==generation)return;if(value.id!==id)throw Error('资料身份不一致，请重新读取。');detail.value=value;void loadHistory(id,turn);await activateTab();}catch(reason){if(turn===generation)showError(reason);}finally{if(turn===generation)loading.value=false;}}
async function activateTab(){if(props.tab==='profile'||props.tab==='directories')await ensureEditing();if(props.tab==='sources')sourcesVisited.value=true;}
function chooseTab(value:CreatorPanelTab){emit('tab',value);}
function tabKey(event:KeyboardEvent,id:CreatorPanelTab){const index=tabs.findIndex(tab=>tab.id===id);let target:number|undefined;if(event.key==='ArrowRight')target=(index+1)%tabs.length;if(event.key==='ArrowLeft')target=(index+tabs.length-1)%tabs.length;if(event.key==='Home')target=0;if(event.key==='End')target=tabs.length-1;if(target===undefined)return;event.preventDefault();chooseTab(tabs[target]!.id);void nextTick(()=>surface.value?.querySelector<HTMLButtonElement>(`#creator-tab-${tabs[target]!.id}`)?.focus());}
function stageAlias(){const value=aliasInput.value.trim();if(value&&!manualAliases.value.includes(value))manualAliases.value.push(value);aliasInput.value='';}
function stageFolder(){if(folderInput.value!==null&&!linkedFolderIds.value.includes(folderInput.value))linkedFolderIds.value.push(folderInput.value);folderInput.value=null;}
async function mutate(action:()=>Promise<void>){if(busy.value||!canEdit.value)return;const turn=generation;busy.value=true;error.value='';notice.value='';collisions.value=[];conflicted.value=false;deletion.value=null;try{await action();}catch(reason){if(!disposed&&turn===generation)showError(reason);}finally{if(!disposed&&turn===generation)busy.value=false;}}
function adoptSaved(result:api.ManagedCreatorSavedState,scope:'profile'|'directories'){const keepProfile=profileDirty.value,keepDirectories=directoriesDirty.value;detail.value=result.creator;editing.value={...result,destination:editing.value!.destination};if(scope==='profile'||!keepProfile)initializeProfile(result);if(scope==='directories'||!keepDirectories)initializeDirectories(result);}
async function refreshSavedAvailability(id:number,turn:number){try{const current=await api.fetchManagedCreatorEditingState(id);if(disposed||turn!==generation)return;editing.value={...editing.value!,destination:current.destination};}catch{if(!disposed&&turn===generation)notice.value='目录设置已保存；可用性信息刷新失败；请关闭并重新打开管理面板核对。';}}
function saved(){reading.invalidate();emit('changed');}
async function saveProfile(){if(props.creatorId!==null&&(!editing.value||!profileDirty.value))return;const id=props.creatorId,turn=generation;let createdId:number|undefined;await mutate(async()=>{if(id===null){const result=await api.createManagedCreator({...draft});if(disposed||turn!==generation)return;profileBaseline.value=profileValue();saved();createdId=result.id;return;}stageAlias();const result=await api.saveManagedCreatorProfile(id,{...draft,manualAliases:[...manualAliases.value],expectedRevision:profileRevision.value});if(disposed||turn!==generation)return;adoptSaved(result,'profile');notice.value='资料已保存';saved();});if(createdId!==undefined&&!disposed&&turn===generation)emit('created',createdId);}
async function saveDirectories(){if(props.creatorId===null||!editing.value||!directoriesDirty.value||invalidPreferred.value)return;const id=props.creatorId,turn=generation;await mutate(async()=>{const result=await api.saveManagedCreatorDirectories(id,{linkedFolderIds:[...linkedFolderIds.value],preferredGalleryFolderId:preferredFolderId.value,expectedRevision:directoriesRevision.value});if(disposed||turn!==generation)return;adoptSaved(result,'directories');notice.value='目录设置已保存';saved();await refreshSavedAvailability(id,turn);});}
async function reloadEditing(){if(props.creatorId===null||busy.value)return;const id=props.creatorId,turn=generation,scope=props.tab;await mutate(async()=>{const result=await api.fetchManagedCreatorEditingState(id);if(disposed||turn!==generation)return;detail.value=result.creator;editing.value=result;if(scope==='profile')initializeProfile(result);if(scope==='directories')initializeDirectories(result);notice.value='已重新读取当前标签；其他标签草稿保留。';});}
async function changeActive(){if(!detail.value||profileDirty.value||directoriesDirty.value)return;const id=detail.value.id,active=!detail.value.isActive,turn=generation;await mutate(async()=>{const result=await api.setManagedCreatorActive(id,active);if(disposed||turn!==generation)return;detail.value=result;stateConfirm.value=false;notice.value=active?'已恢复博主':'已停用博主';saved();try{const current=await api.fetchManagedCreatorEditingState(id);if(disposed||turn!==generation)return;editing.value=current;detail.value=current.creator;initializeProfile(current);initializeDirectories(current);}catch{if(turn===generation){editing.value=null;profileReady.value=false;directoriesReady.value=false;notice.value+='；编辑资料刷新失败，请重新打开标签读取。';}}});}
async function previewDeletion(){if(!detail.value)return;if(dirtyTabs.value.length){notice.value='请先保存或放弃各标签草稿，再检查删除条件。';return;}const id=detail.value.id,turn=generation;await mutate(async()=>{const result=await api.previewManagedCreatorDeletion(id);if(disposed||turn!==generation)return;if(result.creatorId!==id)throw Error('删除条件与当前博主不一致，请重新检查。');deletion.value=result;});}
async function deleteCreator(){const preview=deletion.value;if(dirtyTabs.value.length||!preview?.eligible||preview.blockers.length||!preview.confirmationToken||detail.value?.id!==preview.creatorId)return;const turn=generation;let deleted=false;await mutate(async()=>{const result=await api.deleteUnusedManagedCreator(preview.creatorId,preview.confirmationToken);if(disposed||turn!==generation)return;if(!result.deleted||result.creatorId!==preview.creatorId)throw Error('删除结果尚未确认，请重新检查，不会自动重试。');saved();deleted=true;});if(deleted&&!disposed&&turn===generation)emit('deleted');if(error.value)error.value+=' 请重新检查删除条件，不会自动重试删除。';}
async function sourcePlanned(ids:number[]){emit('source-planned',ids);if(props.creatorId===null)return;const id=props.creatorId,turn=generation;try{const result=await fetchArchiveCatalogCreator(id);if(!disposed&&turn===generation)detail.value=result;}catch(reason){if(turn===generation)showError(reason);}}
function routeInternalLink(event:MouseEvent){if(!router||event.defaultPrevented||event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;const anchor=(event.target as Element)?.closest<HTMLAnchorElement>('a[href]');if(!anchor||anchor.target||anchor.hasAttribute('download'))return;const url=new URL(anchor.href,location.href);if(url.origin!==location.origin)return;event.preventDefault();void router.push(url.pathname+url.search+url.hash);}
function requestLeave():Promise<boolean>{if(auth.ready&&!auth.capabilities.canAccessSettings)return Promise.resolve(true);if(busy.value||sourcePanel.value?.isBusy){notice.value='当前操作正在提交，请等待结果后再切换。';return Promise.resolve(false);}if(!dirtyTabs.value.length)return Promise.resolve(true);if(leaveResolve)return Promise.resolve(false);return new Promise(resolve=>{leaveResolve=resolve;leaveDialog.value?.showModal();});}
function resolveLeave(value:boolean){const resolve=leaveResolve;leaveResolve=null;leaveDialog.value?.close();resolve?.(value);}
function returnToSave(){chooseTab(dirtyTabs.value[0]??'profile');resolveLeave(false);}
function resizeSurface(){const element=surface.value;if(!element)return;const active=document.activeElement as HTMLElement|null;narrow.value=media?.matches??false;if(element.open)element.close();if(narrow.value)element.showModal();else element.show();if(active&&element.contains(active))active.focus({preventScroll:true});}
function beforeUnload(event:BeforeUnloadEvent){if(dirtyTabs.value.length||busy.value){event.preventDefault();event.returnValue='';}}
let surfaceMounted=false, initiallyPositioned=false;
function positionInitialPanel(){if(!surfaceMounted||!props.layoutReady||loading.value||editingLoading.value||historyLoading.value||initiallyPositioned)return;initiallyPositioned=true;if(!narrow.value&&surface.value&&surface.value.getBoundingClientRect().top>window.innerHeight/2)surface.value.scrollIntoView({block:'start',behavior:'auto'});}
watch([()=>props.layoutReady,loading,editingLoading,historyLoading],async()=>{await nextTick();if(!disposed)positionInitialPanel();});
watch(dirtyTabs,tabs=>{if(tabs.length)deletion.value=null;});
watch(()=>props.creatorId,loadIdentity,{immediate:true});watch(()=>props.tab,activateTab);
watch(()=>auth.capabilities.canAccessSettings,value=>{if(auth.ready&&!value){++generation;busy.value=false;loading.value=false;editingLoading.value=false;profileReady.value=false;directoriesReady.value=false;sourcesVisited.value=false;detail.value=null;editing.value=null;editingPromise=null;manualAliases.value=[];aliasInput.value='';linkedFolderIds.value=[];preferredFolderId.value=null;Object.assign(draft,{name:'',preference:null,rating:null,confirmDistinct:false});resolveLeave(true);emit('close');}});
onMounted(()=>{media=window.matchMedia?.('(max-width:1100px)')??null;media?.addEventListener('change',resizeSurface);resizeSurface();surfaceMounted=true;positionInitialPanel();window.addEventListener('beforeunload',beforeUnload);});
onBeforeUnmount(()=>{disposed=true;++generation;resolveLeave(false);media?.removeEventListener('change',resizeSurface);window.removeEventListener('beforeunload',beforeUnload);surface.value?.close();});
defineExpose({requestLeave,dirtyTabs});
</script>

