px solid var(--accent);outline-offset:2px}a{color:var(--accent);text-decoration:none;font-size:.85rem}.quick-links{display:flex;gap:.7rem;align-items:center;flex-wrap:wrap;margin-bottom:.5rem}.quick-links a{padding:.5rem .7rem;border:1px solid var(--border);border-radius:.5rem}.hint,small{color:var(--muted);font-size:.78rem;line-height:1.65}.records,.editable-list{list-style:none;margin:0;padding:0;display:grid;gap:.65rem;overflow-wrap:anywhere}.records li{font-size:.85rem}.records small,.editable-list small{display:block}.editable-list li{display:flex;align-items:center;justify-content:space-between;gap:.5rem;font-size:.85rem}.editable-list span{min-width:0;overflow-wrap:anywhere}.records{max-height:20rem;overflow:auto}.error{padding:.7rem;background:#fee2e2;color:#991b1b;border-radius:.5rem;font-size:.85rem}.notice{padding:.6rem;background:var(--bg);border-radius:.5rem;font-size:.85rem}.warning{padding:.85rem;border:1px solid var(--border);background:var(--bg);border-radius:.5rem;margin-top:1rem;font-size:.85rem}.warning button{margin:.35rem .3rem 0 0}.warning ul{padding-left:1.2rem}.warning .check{display:flex;gap:.5rem;align-items:center}fieldset{border:0;margin:0;padding:0;min-width:0;display:grid;gap:.85rem}label{display:grid;gap:.4rem;font-size:.85rem}input:not([type=checkbox]),select{width:100%;box-sizing:border-box;min-width:0;padding:.6rem;border:1px solid var(--border);background:var(--bg);color:var(--text);border-radius:.5rem}.field-pair{display:grid;grid-template-columns:1fr 1fr;gap:.7rem}.inline-input{display:flex;gap:.5rem;align-items:end}.inline-input label{flex:1;min-width:0}.save-bar{position:sticky;bottom:-1.25rem;display:flex;align-items:center;justify-content:space-between;gap:.8rem;background:var(--surface);border-top:1px solid var(--border);padding:1rem 0;margin:1.2rem 0 0;z-index:1}.save-bar span{font-size:.75rem;color:var(--muted)}.save-bar button{flex-shrink:0}.danger-zone{padding-top:1.2rem;margin-top:1.5rem}.danger-zone>div{margin-top:1rem}.technical{margin-top:1.2rem;font-size:.75rem;color:var(--muted);overflow-wrap:anywhere}.technical summary{cursor:pointer}.technical ul{padding-left:1rem}.leave-dialog{margin:auto;max-width:26rem;width:calc(100vw - 3rem);padding:1.3rem;background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:.8rem}.leave-actions{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:1rem}@media(max-width:1100px){.creator-panel{position:fixed;inset:0 0 0 auto;margin:0;width:min(37rem,100vw);height:100dvh;max-height:100dvh;border-radius:1rem 0 0 1rem;top:0}}@media(max-width:480px){.creator-panel{padding:1rem;border-radius:0}.panel-metrics{grid-template-columns:repeat(3,minmax(0,1fr));gap:.7rem}.save-bar{bottom:-1rem}.panel-tabs button{font-size:.75rem}.field-pair{gap:.5rem}.inline-input{flex-wrap:wrap}.inline-input label{flex-basis:100%}}
</style>
